def solve():
    good_numbers = []
    for a in range(1, 10):
        for b in range(1, 10):
            if a == b:
                continue

            m = 10 * a + b

            # Check Condition 1: a divides m
            # Since m = 10a + b, this is equivalent to a | b
            cond1 = (b % a == 0)

            # Check Condition 2: b divides m
            # Since m = 10a + b, this is equivalent to b | 10a
            cond2 = ((10 * a) % b == 0)

            if cond1 or cond2:
                good_numbers.append(m)

    return sorted(good_numbers)

