def is_good(n):
    s = str(n)
    if len(s) == 1:
        return True

    for i in range(len(s)):
        # Removing digit at index i
        d_str = s[:i] + s[i+1:]
        d = int(d_str)
        # Condition: d must be a divisor of n and d must be a good number.
        if d != 0 and n % d == 0 and is_good(d):
            return True
    return False

