def find_all_good_numbers():
    good_numbers = set()
    for i in range(1, 10):
        good_numbers.add(i)

    for num_digits in range(2, 10):
        # We need to check all numbers with num_digits
        # But we only care about those with distinct nonzero digits.
        # Let's generate them.
        import itertools
        for digits in itertools.permutations(range(1, 10), num_digits):
            n = int("".join(map(str, digits)))
            s = str(n)
            for j in range(len(s)):
                d_str = s[:j] + s[j+1:]
                if d_str:
                    d = int(d_str)
                    if d in good_numbers and n % d == 0:
                        good_numbers.add(n)
                        break
    return good_numbers

